// === Tab: mySketch ===
// by SamuelYAN
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

// genuary 2024
// JAN. 2 (credit: Luis Fraguada)
// No palettes.

let mySize;
let theShader;

function preload() {
	theShader = createShader(vert, frag)
}

function setup() {
	mySize = max(windowWidth, windowHeight);
	createCanvas(mySize, mySize, WEBGL);
	noStroke();
}

function draw() {
	shader(theShader);

	theShader.setUniform("u_resolution", [width, height]);
	theShader.setUniform("u_time", frameCount * 0.05);
	theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0) / height]);

	rect(0, 0, width, height);
}


// === Tab: frag ===
const frag = `
#ifdef GL_ES
precision highp float;
#endif

#define PI 3.14159265358979323846

uniform vec2 u_resolution;
uniform float u_time;


float random (in vec2 _st) {
    return fract(sin(dot(_st.xy,
                         vec2(12.9898,78.233)))*
        43758.5453123);
}

vec2 rotate2D (vec2 _st, float _angle) {
    _st -= 1.;
    _st =  mat2(cos(_angle),-sin(_angle),
                sin(_angle),cos(_angle)) * _st;
    _st += 0.25;
    return _st;
}

vec2 tile (vec2 _st, float _zoom) {
    _st *= _zoom;
    return fract(_st);
}

vec2 rotateTilePattern(vec2 _st){

    //  Scale the coordinate system by 2x2
    _st *= 4.0;

    //  Give each cell an index number
    //  according to its position
    float index = 1.;
    index += step(1., mod(_st.x,12.0))* 2.;
    index += step(1., mod(_st.y,1.))*1.;

    // Make each cell between 0.0 - 1.0
     _st = floor(_st);

    // Rotate each cell according to the index
    if(index == 1.0){
        _st = rotate2D(_st,PI*0.25);
    } else if(index == 2.0){
        _st = rotate2D(_st,PI*-1.);
    } else if(index == 3.0){
        _st = rotate2D(_st,PI*0.5);
    }else if(index == 4.0){
        _st = rotate2D(_st,PI*-0.5);
    }

    return _st;
}


void main (void) {
    vec2 st = gl_FragCoord.xy/u_resolution.xy;
    // st.y *= u_resolution.x / u_resolution.y;
    st.x*= u_resolution.x / u_resolution.y;
    st = tile(st, 1.0);
    st *= rotateTilePattern(st);

    // Make more interesting combinations
     st = tile(st,12.0);
     st = rotate2D(1.-st,PI*u_time*0.1);
     st = rotateTilePattern(1.-st*2.);
     st /= rotate2D(st,-PI *u_time*0.);

    // step(st.x,st.y) just makes a b&w triangles
    // but you can use whatever design you want.
    gl_FragColor = vec4(vec3(step(st.x,st.y),step(st.x,st.y),step(st.x,st.y)),1.0);
}

`

// === Tab: vert ===
const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

attribute vec3 aPosition;
attribute vec2 aTexCoord;

void main() {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
  gl_Position = positionVec4;
}
`;

